struct Ticket: ~Copyable { let seat: Int }
do {
    let t = Ticket(seat: 7)
    let u = t // moved, not copied
    print(u.seat)
}

struct Ticket: ~Copyable { let seat: Int }
func show(_ t: borrowing Ticket) {
    print("Seat \(t.seat)")
}
let t = Ticket(seat: 7)
show(t); show(t)

struct Ticket: ~Copyable { let seat: Int }
func use(_ t: consuming Ticket) {
    print("Used seat \(t.seat)")
}
do { let t = Ticket(seat: 7); use(t) }

